INSERT INTO animals (slug,name_ko,name_en,name_scientific,category,lifespan_min,lifespan_max,height_min,height_max,weight_min,weight_max,habitat,diet,description,fun_fact,image_url,sound_url,tags) VALUES 
('bison','들소','Bison','Bison bison','land',15,20,150,180,300,1000,'{"초원","평원","북아메리카"}','herbivore','들소는 북아메리카에 살고 있는 아주 크고 털이 복슬복슬한 동물 친구예요. 등에 툭 튀어나온 혹과 튼튼한 다리, 뾰족한 뿔이 특징이랍니다. 주로 넓은 풀밭에서 무리지어 풀을 뜯어 먹으며 살아요. 보기보다 아주 빠르게 달릴 수 있는 동물이에요.','아주아주 옛날에는 북아메리카 땅에 들소가 셀 수 없을 만큼 많아서, 이동할 때 땅이 흔들리고 하늘이 까맣게 보일 정도였다고 해요!','https://images.unsplash.com/photo-1730221176590-dbf1bbf3373e?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxCaXNvbiUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIxMTM5fDA&ixlib=rb-4.1.0&q=80&w=1080','','{"북미동물","초원동물","평원","큰몸","뿔달린","털복숭이","초식동물","무리지어사는","힘센","빠른달리기","온순한동물","아메리카들소","야생"}'),
('brown-bear','갈색곰','Brown Bear','Ursus arctos','land',20,30,90,150,180,600,'{"유라시아","북아메리카"}','omnivo','갈색곰은 유라시아와 북아메리카에 사는 아주 커다란 곰이야. 몸집이 정말 크고, 때로는 북극곰만큼이나 거대하단다. 수컷 곰은 암컷보다 훨씬 크고 힘이 세 보여. 털 색깔도 크림색부터 짙은 갈색까지 다양해.','갈색곰은 흙을 잘 파기 위해 다른 곰들에게는 없는 특별한 어깨 근육 혹이 있대! 그리고 발이 정말 커서 앞발은 최대 21cm, 뒷발은 36cm나 된대!','https://images.unsplash.com/photo-1665153728489-d9ffc2d5de3b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxCcm93biUyMEJlYXIlMjBhbmltYWx8ZW58MHwwfHx8MTc3NzUyMDkwM3ww&ixlib=rb-4.1.0&q=80&w=1080','','{"갈색곰","큰곰","유라시아","북아메리카","잡식동물","육상동물","힘센동물","큰발","어깨혹","땅파기","털색깔다양","수컷큼","야생동물","숲속동물"}'),
('camel','낙타','Camel','Camelus','land',0,0,0,0,0,0,'{"사막"}','herbivore','낙타는 등에 ''혹''이라는 특별한 주머니를 가지고 있는 멋진 동물이야. 이 혹은 낙타가 뜨거운 사막에서도 며칠 동안 끄떡없이 잘 지낼 수 있게 도와준단다. 사람들은 낙타 덕분에 사막에서 짐을 나르거나 여행을 할 수 있어. 혹이 하나인 낙타와 혹이 두 개인 낙타, 두 가지 종류가 있단다!','전 세계 낙타의 94%는 등에 혹이 하나뿐인 단봉낙타이고, 혹이 두 개인 쌍봉낙타는 6%밖에 안 된대! 정말 신기하지?','https://images.unsplash.com/photo-1759306757973-dc11b1db2afe?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxDYW1lbCUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIxMDIwfDA&ixlib=rb-4.1.0&q=80&w=1080','','{"사막동물","혹","가축","운송수단","초식동물","지방주머니","더위에강한","낙타과","발굽동물","여행친구","아시아동물","아프리카동물","쌍봉낙타","단봉낙타","멸종위기동물"}'),
('cheetah','치타','Cheetah','Acinonyx jubatus','land',0,0,67,94,21,65,'{}','carnivore','치타는 땅 위에서 가장 빨리 달릴 수 있는 동물 친구예요! 시속 100km가 넘는 속도로 달릴 수 있답니다. 몸에는 까만 점박이 무늬가 있고, 눈에는 마치 눈물 자국처럼 보이는 까만 줄무늬가 있어요. 길고 유연한 몸과 튼튼한 다리 덕분에 아주 빠르게 달릴 수 있답니다.','우와! 치타는 세상에서 가장 빠른 육상 동물이에요. 먹이를 잡을 때 마치 자동차처럼 아주 빠른 속도로 질주할 수 있어요!','https://images.unsplash.com/photo-1626111266180-6d76d58a45e5?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxDaGVldGFoJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA3OTl8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"가장빠른동물","육상동물","육식동물","점박이무늬","검은눈물자국","고양이과","사냥꾼","빠른달리기","긴다리","유연한척추","포식자","강한뒷다리근육","타우니색털","크림색털"}'),
('chimpanzee','침팬지','Chimpanzee','Pan troglodytes','land',30,50,100,170,27,70,'{"아프리카 열대 숲","사바나"}','omnivore','침팬지는 아프리카의 따뜻한 숲과 풀밭에 사는 똑똑한 유인원 친구예요. 사람과 아주 많이 닮아서 ''큰 원숭이''라고도 불려요. 풀, 과일, 곤충은 물론 작은 동물까지 먹는 잡식성 동물이며, 나무 위에서 재밌게 생활한답니다. 안타깝게도 지금은 사라질 위험에 처해 있는 소중한 동물이에요.','침팬지는 나뭇가지나 돌멩이를 도구처럼 사용해서 맛있는 먹이를 찾거나 딱딱한 견과류를 깨트려 먹을 줄 아는 아주 영리한 동물이랍니다!','https://images.unsplash.com/photo-1559629304-47a70c8c042e?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxDaGltcGFuemVlJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA4Nzd8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"유인원","아프리카","숲","사바나","잡식성","멸종위기","영리한","도구사용","사회성","나무타기","검은털","열대지방","큰원숭이","무리생활"}'),
('deer','사슴','Deer','Cervidae','land',10,20,60,150,10,250,'{"숲","초원","산"}','herbivore','안녕! 나는 숲속의 멋쟁이 사슴이야. 우리 사슴은 풀이나 나뭇잎을 먹고 사는 친구들이란다. 남자 사슴들은 해마다 새로운 뿔이 자랐다가 다시 떨어지는데, 이 뿔은 머리에서 뼈가 자라난 거야. 가끔 다른 남자 사슴들과 힘겨루기를 할 때 사용하기도 해.','사슴의 뿔은 정말 빠르게 자랄 수 있어! 어떤 사슴은 하루에 2.5cm씩 뿔이 자라기도 한대. 정말 신기하지?','https://images.unsplash.com/photo-1654555277423-4c11c3effa24?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxEZWVyJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA5NTJ8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"숲","초원","산","초식동물","풀먹는동물","발굽동물","야생동물","뿔","튼튼한발굽","멋진뿔","뿔싸움","무리생활","귀여운동물","숲의친구"}'),
('elephant','코끼리','Elephant','Elephantidae','land',60,70,240,400,2000,6000,'{"아프리카","아시아"}','herbivore','코끼리는 세상에서 가장 큰 땅 위 동물이야! 길고 튼튼한 코(코끼리 코)와 커다란 귀, 그리고 뾰족한 상아가 특징이지. 이 커다란 코로 풀과 나뭇잎을 먹고 물도 마셔. 몸은 크지만 아주 똑똑하고 자기 가족을 소중히 여기는 동물이야.','코끼리의 긴 코는 무려 4만 개가 넘는 근육으로 이루어져 있대! 그래서 아주 무거운 통나무도 번쩍 들 수 있고, 땅에 떨어진 작은 풀잎 한 장도 섬세하게 집어 올릴 수 있단다!','https://images.unsplash.com/photo-1707759408965-b273baf8b217?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxFbGVwaGFudCUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIwNzQ4fDA&ixlib=rb-4.1.0&q=80&w=1080','','{"육상동물","초식동물","큰귀","긴코","상아","아프리카","아시아","회색피부","덩치큰동물","똑똑한동물","사회적인동물","기둥다리","포유류","땅파기","무거운"}'),
('fox','여우','Fox','Vulpes vulpes','land',2,5,35,50,3,9,'{"숲","초원","산","도시 근처","북아메리카","유럽","아시아","아프리카","호주"}','carnivore','안녕! 나는 여우야. 나는 세상에서 가장 널리 퍼져 사는 여우 중 하나란다. 북아메리카, 유럽, 아시아뿐만 아니라 아프리카와 멀리 호주까지 다양한 곳에서 만날 수 있어. 작은 쥐나 주머니쥐 같은 동물을 사냥해서 먹고 살아. 사람들과 가까운 곳에서도 잘 지내는 아주 똑똑한 동물이야.','우와! 여우는 정말 놀라운 적응력을 가졌어! 북아메리카, 유럽, 아시아, 아프리카는 물론 심지어 호주까지, 지구의 아주 많은 곳에서 여우를 만날 수 있단다!','https://images.unsplash.com/photo-1715430306822-6961509374e6?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxGb3glMjBhbmltYWx8ZW58MHwwfHx8MTc3NzUyMDkzNnww&ixlib=rb-4.1.0&q=80&w=1080','','{"여우","붉은여우","가장큰여우","북반구동물","전세계","숲속동물","초원동물","육식동물","사냥꾼","똑똑한","민첩한","야행성","적응력강한","꼬리풍성","도시근처"}'),
('giant-panda','판다','Giant Panda','Ailuropoda melanoleuca','land',0,0,120,190,100,115,'{"중국"}','herbivore','안녕하세요! 나는 자이언트 판다예요. 나는 하얀 털에 눈 주변, 귀, 다리, 어깨에 검은 점박이 무늬를 가지고 있어요. 몸은 아주 통통하고 귀엽답니다! 나는 중국에 살며, 주로 대나무와 죽순만 먹고 살아요.','나는 앞발에 대나무를 꽉 잡을 수 있는 특별한 ''엄지손가락''이 있어요! 덕분에 맛있는 대나무를 편하게 먹을 수 있답니다!','https://images.unsplash.com/photo-1659540462073-1d12c51daad8?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxHaWFudCUyMFBhbmRhJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjEwMDJ8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"판다","자이언트판다","중국동물","곰과동물","하얀색털","검은색무늬","얼룩무늬","통통한몸","큰몸집","초식동물","대나무전문가","특별한엄지","숲속친구"}'),
('giraffe','기린','Giraffe','Giraffa camelopardalis','land',15,25,400,570,800,1900,'{"아프리카","사바나","초원"}','herbivore','기린은 아프리카에 사는 아주 키 큰 동물 친구예요. 긴 목과 멋진 얼룩무늬 옷을 입고 다니죠. 지구에서 가장 키가 큰 동물로, 높은 나무 꼭대기에 있는 나뭇잎도 냠냠 먹을 수 있어요. 온순하고 평화로운 동물이랍니다.','기린은 혀가 무려 45~50cm나 길어서 자기 코도 핥을 수 있고, 가시 돋친 나뭇잎도 쉽게 먹을 수 있답니다!','https://images.unsplash.com/photo-1554467469-2cb4e140f8d7?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxHaXJhZmZlJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA3Njd8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"아프리카","초식동물","키다리","긴목","얼룩무늬","사바나","포유류","반추동물","평화로운동물","나뭇잎식사","우아함","높은키","뿔","사회생활"}'),
('gorilla','고릴라','Gorilla','Gorilla','land',35,50,120,180,60,200,'{"적도 아프리카의 열대 우림"}','herbivore','고릴라는 아프리카 숲에 사는 아주 크고 힘센 친구들이에요. 주로 풀이나 나뭇잎, 열매 같은 식물만 먹고 산답니다. 덩치가 크지만 사실은 아주 온순하고 가족을 사랑하는 동물이에요. 숲 속에서 조용히 가족과 함께 지내는 것을 좋아해요.','고릴라의 DNA는 우리 사람과 정말 비슷해서, 무려 96%에서 99%까지 똑같대요! 정말 신기하죠?','https://images.unsplash.com/photo-1634200009251-ed3110fb0977?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxHb3JpbGxhJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA4NjR8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"아프리카동물","열대우림","숲속친구","초식동물","채식주의자","가족중심","영장류","평화로운동물","무리지어사는","큰몸집","강한힘","회색등","검은털","똑똑한동물"}'),
('hedgehog','고슴도치','Hedgehog','Erinaceinae','land',2,7,10,30,0.15,1.5,'{"유럽","아시아","아프리카","숲","초원","정원"}','omnivorous','안녕! 나는 등에 뾰족뾰족한 가시를 가진 귀여운 고슴도치야. 유럽, 아시아, 아프리카의 숲과 초원, 심지어 정원에서도 살지. 주로 밤에 돌아다니며 벌레나 작은 열매를 먹어. 위험할 땐 몸을 둥글게 말아 가시로 스스로를 지킨단다!','고슴도치는 신기하게도 처음 맡는 냄새나 맛있는 걸 발견하면 거품 같은 침을 만들어서 자기 등 가시에 발라! 왜 그런지는 아직 아무도 정확히 모르지만, 아마 친구들에게 자랑하는 걸지도 몰라!','https://images.unsplash.com/photo-1589832027052-c54a38474fa3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxIZWRnZWhvZyUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIxMTIzfDA&ixlib=rb-4.1.0&q=80&w=1080','','{"가시동물","뾰족한등","밤에활동","작은동물","숲동물","초원동물","정원친구","잡식성","겨울잠","몸을말아","야행성","유럽동물","아시아동물","아프리카동물"}'),
('hippopotamus','하마','Hippopotamus','Hippopotamus amphibius','land',40,50,130,165,1300,1800,'{"사하라 이남 아프리카","강","호수","물가"}','herbivore','하마는 아프리카에 사는 아주아주 큰 동물 친구예요. 몸이 무거워서 육지에서는 느려 보이지만, 물속에서는 진짜 선수처럼 빠르고 날렵하게 헤엄친답니다! 낮에는 시원한 강이나 호수에서 쉬고, 밤이 되면 나와서 맛있는 풀들을 먹어요. ''강의 말''이라는 뜻의 이름처럼 물을 아주 좋아하는 친구랍니다.','하마는 피부가 햇볕에 타지 않도록 몸에서 분홍색이나 붉은색의 신기한 땀을 흘려요! 이 땀은 피부를 촉촉하게 지켜주고 세균도 막아주는 마법 같은 역할을 한답니다. 우와, 신기하죠?','https://images.unsplash.com/photo-1761602861946-ef12b312910a?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxIaXBwb3BvdGFtdXMlMjBhbmltYWx8ZW58MHwwfHx8MTc3NzUyMDg0N3ww&ixlib=rb-4.1.0&q=80&w=1080','','{"하마","아프리카동물","강의말","초식동물","반수생","덩치큰동물","물속에서사는","사하라_이남_아프리카","두꺼운피부","잠수능력","무리생활","풀먹는동물","느린듯빠른","핑크땀","수영잘하는"}'),
('hyena','하이에나','Hyena','Hyaenidae','land',10,25,70,90,40,82,'{"아프리카","사바나","초원","숲"}','carnivore','하이에나는 아프리카에 사는 아주 특별한 동물 친구예요. 밤에 주로 활동하며, 무서운 웃음소리를 내지만 사실은 서로 이야기하는 소리랍니다. 뼈도 와작 깨부수는 아주 튼튼한 턱을 가졌고, 똑똑하게 무리를 지어 생활해요.','우와! 하이에나 무리에서는 암컷 하이에나가 대장이라는 사실을 알고 있었나요? 수컷보다 몸집도 더 크고 힘도 세서, 무리를 이끌어간답니다!','https://images.unsplash.com/photo-1664699412070-9e9f2313bf28?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxIeWVuYSUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIxMDUyfDA&ixlib=rb-4.1.0&q=80&w=1080','','{"아프리카","사바나","초원","육식동물","청소부","사냥꾼","무리생활","야행성","강한턱","독특한웃음소리","영리함","포유류","여성우위","튼튼한이빨"}'),
('jaguar','재규어','Jaguar','Panthera onca','land',12,15,63,76,56,158,'{"아메리카","열대우림","습지","강가"}','carnivore','재규어는 아메리카 대륙에서 가장 크고 멋진 고양이과 동물이에요. 노란색 털에 예쁜 점박이 무늬가 특징이고, 가끔 검은색 재규어도 볼 수 있답니다. 몸길이가 1.8미터가 넘고 몸무게도 아주 많이 나가는 힘센 동물이지요. 거북이 등껍질도 깨뜨릴 수 있는 아주 강한 턱을 가지고 있어요.','재규어는 다른 고양이들과 다르게 사냥감을 잡을 때, 머리뼈를 한 번에 물어서 뇌를 공격한대요! 정말 놀랍도록 강력한 힘을 가졌죠?','https://images.unsplash.com/photo-1566544496485-02b11e54229b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxKYWd1YXIlMjBhbmltYWx8ZW58MHwwfHx8MTc3NzUyMTAzN3ww&ixlib=rb-4.1.0&q=80&w=1080','','{"아메리카동물","고양이과","육식동물","열대우림","강가","습지","점박이","강한턱","사냥꾼","큰고양이","은밀한","강력한","수영잘하는"}'),
('kangaroo','캥거루','Kangaroo','Macropus spp.','land',0,0,0,0,0,0,'{"호주","뉴기니"}','herbivore','캥거루는 호주와 뉴기니에 사는 아주 특별한 동물이에요. 폴짝폴짝 뛰는 튼튼한 다리와 아기를 키우는 배 주머니가 가장 큰 특징이랍니다. 빨간 캥거루, 회색 캥거루 등 여러 종류가 있으며, 주로 풀을 먹고 살아요. 풀밭에서 껑충껑충 뛰어다니는 모습이 정말 멋져요.','캥거루 아기는 엄마 배에 있는 따뜻하고 안전한 주머니(육아낭) 안에서 세상 밖으로 나올 때까지 자란답니다! 아늑한 엄마 주머니 속에서 고개를 내미는 아기의 모습이 정말 귀여워요.','https://images.unsplash.com/photo-1626474612474-c7d0bfc359fb?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxLYW5nYXJvbyUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIwOTY4fDA&ixlib=rb-4.1.0&q=80&w=1080','','{"호주동물","유대류","아기주머니","껑충껑충","초식동물","점프","큰꼬리","야생동물","귀여운동물","초원동물","캥거루가족","뉴기니동물","강한다리"}'),
('koala','코알라','Koala','Phascolarctos cinereus','land',0,0,60,85,4,15,'{"호주 동부 해안","호주 남부 해안","퀸즐랜드","뉴사우스웨일스","빅토리아","사우스오스트레일리아"}','herbivore','코알라는 호주에 사는 귀여운 유대류 동물 친구예요. 통통한 몸에 꼬리가 없고, 솜털 같은 귀와 커다란 코가 특징이랍니다. 코알라는 유칼립투스 잎만 먹고 나무 위에서 살며, 하루의 대부분을 잠을 자면서 보낸대요. 아기 코알라는 엄마 배 주머니에서 안전하게 자란답니다!','코알라는 곰처럼 보이지만, 사실 캥거루와 더 가까운 주머니 동물(유대류)이래요!','https://images.unsplash.com/photo-1580159524235-c50b9b9d3996?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxLb2FsYSUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIwOTg0fDA&ixlib=rb-4.1.0&q=80&w=1080','','{"호주동물","초식동물","유대류","나무타기","잠꾸러기","솜털귀","큰코","꼬리없음","회색털","갈색털","유칼립투스먹는동물","귀여운동물","포유류","순한동물","온순한동물"}'),
('komodo-dragon','코모도왕도마뱀','Komodo Dragon','Varanus komodoensis','land',0,0,0,0,0,150,'{"인도네시아","코모도섬","린카섬","플로레스섬","길리 다사미섬","길리 모탕섬","코모도 국립공원"}','carnivore','코모도왕도마뱀은 지구에서 가장 큰 도마뱀이에요. 몸길이가 3미터까지 자라고 몸무게는 150kg이나 나가는 거대한 파충류랍니다. 인도네시아의 여러 섬에서 살고 있으며, 그 모습이 마치 전설 속 용 같아요!','코모도왕도마뱀은 지구에서 가장 큰 도마뱀으로, 몸길이가 작은 자동차만큼이나 길어요! 마치 진짜 용처럼 생겼답니다. 우와!','https://images.unsplash.com/photo-1648726442622-5cd3abeccaa8?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxLb21vZG8lMjBEcmFnb24lMjBhbmltYWx8ZW58MHwwfHx8MTc3NzUyMTE3NXww&ixlib=rb-4.1.0&q=80&w=1080','','{"코모도왕도마뱀","인도네시아","가장큰도마뱀","육식동물","파충류","섬에사는동물","코모도국립공원","무서운사냥꾼","거대동물","용처럼생긴","긴꼬리","비늘가죽","강력한턱","멸종위기동물"}'),
('leopard','표범','Leopard','Panthera pardus','land',0,0,60,70,20.5,72,'{}','carnivore','표범은 커다란 고양이과 동물 중 하나예요. 몸은 날씬하고 힘이 세며, 노랗거나 황금색 털에 장미꽃처럼 모여 있는 검은 점무늬가 있어요. 이 멋진 점무늬 덕분에 숲속에 숨어있기 아주 좋답니다.','표범은 자기 몸보다 훨씬 무거운 먹이를 물고 나무 위로 올라갈 수 있는 엄청난 힘을 가졌대요! 정말 놀랍지 않나요?','https://images.unsplash.com/photo-1664699268523-5836e28d26f0?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxMZW9wYXJkJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA4MTR8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"고양이과","육식동물","점박이무늬","날씬한몸","근육질","긴꼬리","황금색털","야생동물","맹수","사냥꾼","강력한","재빠른"}'),
('lion','사자','Lion','Panthera leo','land',10,14,90,120,120,250,'{"사하라 이남 아프리카","인도"}','carnivore','사자는 아주 멋진 큰 고양이과 동물이야. 튼튼한 몸과 둥근 귀, 그리고 꼬리 끝에는 털뭉치 장식이 있지. 특히 수컷 사자는 갈기라고 불리는 풍성한 털을 가지고 있어서 더욱 멋져 보여. 아프리카와 인도에서 무리를 지어 생활한단다.','사자는 정글의 왕답게 아주 큰 소리로 ''어흥!'' 하고 울부짖을 수 있어. 이 소리는 무려 8km 밖에서도 들릴 정도로 정말 크고 멋지단다!','https://images.unsplash.com/photo-1670597691488-ab98c81d1516?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxMaW9uJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjAzOTF8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"아프리카동물","인도동물","초원동물","육식동물","사냥꾼","사회적동물","무리지어생활","갈기","큰고양이과","튼튼한몸","꼬리털뭉치","맹수","왕의포효"}'),
('meerkat','미어캣','Meerkat','학명','land',0,0,24,35,0.62,0.97,'{"남아프리카","건조한 사막"}','carnivore','안녕! 나는 미어캣이야. 남아프리카의 뜨거운 땅에서 친구들과 함께 살아가지. 나는 큰 눈과 뾰족한 코, 그리고 등에 예쁜 줄무늬가 있어. 발톱으로 땅을 아주 잘 파서 굴을 만들고 그 안에서 잠을 자고 쉬기도 한단다.','나는 키가 작지만, 아주 먼 곳까지 잘 볼 수 있어! 가족들을 위해 두 발로 서서 주변을 살펴보고 위험이 없는지 망을 보는 멋진 경계병 역할도 한단다!','https://images.unsplash.com/photo-1765377790900-85ba28008322?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxNZWVya2F0JTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjEwNjd8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"남아프리카","건조한지역","사막","육식동물","곤충먹는동물","땅파기","굴속생활","무리생활","사회적동물","경계병","작은동물","회색털","줄무늬","튼튼한발톱","체온조절"}'),
('orangutan','오랑우탄','Orangutan','Pongo','land',30,50,100,140,30,90,'{"인도네시아 열대우림","말레이시아 열대우림","보르네오","수마트라"}','omnivore','오랑우탄은 인도네시아와 말레이시아의 따뜻한 열대우림에 살고 있는 아주 특별한 유인원 친구들이에요. 길고 붉은 털과 긴 팔을 가지고 있어서 나무 사이를 멋지게 건너다니는 것을 아주 좋아한답니다. 주로 보르네오와 수마트라 섬에서 볼 수 있어요. 예전에는 더 넓은 지역에 살았지만 지금은 이 지역에만 남아있어요.','오랑우탄은 평생의 대부분을 나무 위에서 보내고, 땅으로 잘 내려오지 않는답니다!','https://images.unsplash.com/photo-1630509930233-0053317bf0ec?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxPcmFuZ3V0YW4lMjBhbmltYWx8ZW58MHwwfHx8MTc3NzUyMTA4N3ww&ixlib=rb-4.1.0&q=80&w=1080','','{"유인원","열대우림","인도네시아","말레이시아","보르네오","수마트라","나무위생활","긴팔","붉은털","잡식동물","나무타기","영리한동물","멸종위기동물","포유류","숲의사람"}'),
('polar-bear','북극곰','Polar Bear','Ursus maritimus','land',15,18,100,160,150,800,'{"북극","북극 주변 지역"}','carnivore','북극곰은 아주 추운 북극에 사는 커다란 흰색 곰이에요. 두꺼운 털과 지방 덕분에 얼음 위에서도 전혀 춥지 않아요. 맛있는 고기를 사냥해서 먹는 육식 동물이고, 커다란 발로 얼음 위를 걷거나 물속에서 헤엄치는 것도 아주 잘한답니다.','혹시 알고 있었나요? 북극곰의 하얗거나 노르스름한 털 아래에는 사실 새까만 피부가 숨어 있어요! 이 검은 피부가 햇빛을 흡수해서 북극곰의 몸을 따뜻하게 지켜준답니다.','https://images.unsplash.com/photo-1677146710299-d45d063e0cdf?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxQb2xhciUyMEJlYXIlMjBhbmltYWx8ZW58MHwwfHx8MTc3NzUyMDkyMHww&ixlib=rb-4.1.0&q=80&w=1080','','{"북극","육식동물","큰곰","흰색털","검은피부","수영잘하는","얼음","사냥꾼","두꺼운털","겨울","강력한","혼자사는","발이큰"}'),
('raccoon','라쿤','Raccoon','Procyon lotor','land',0,0,40,70,5,26,'{"북아메리카"}','omnivore','라쿤은 북아메리카에 사는 귀여운 동물 친구예요. 밤에 돌아다니면서 맛있는 것을 찾아 먹는 잡식 동물이랍니다. 앞발이 아주 재주가 많아서 먹이를 잘 잡고, 눈 주변의 검은 가면과 줄무늬 꼬리가 특징이에요. 똑똑하고 호기심도 많답니다!','라쿤은 정말 똑똑해서, 한 번 배운 걸 무려 3년 동안이나 기억할 수 있대요! 우와, 정말 대단하죠?','https://images.unsplash.com/photo-1615048907113-0046d8692056?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxSYWNjb29uJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjExMDN8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"북아메리카","잡식동물","야행성","회색털","가면얼굴","줄무늬꼬리","재주많은앞발","똑똑한동물","기억력좋은","영리한","호기심많은"}'),
('rhinoceros','코뿔소','Rhinoceros','Rhinocerotidae','land',35,50,140,185,800,2300,'{"아프리카","남아시아","동남아시아"}','herbivore','코뿔소는 아주 크고 튼튼한 동물이에요. 코 위에 멋진 뿔이 하나 또는 두 개 달려있죠. 주로 아프리카와 아시아의 따뜻한 초원이나 숲에서 풀과 나뭇잎을 먹고 살아요. 덩치는 크지만 무척 온순한 친구랍니다.','코뿔소의 뿔은 우리 손톱이나 머리카락처럼 ''케라틴''이라는 물질로 만들어져 있어요. 뼈가 아니라는 사실, 정말 신기하죠?','https://images.unsplash.com/photo-1556080258-a808c481f0ea?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxSaGlub2Nlcm9zJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA4MzN8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"아프리카","아시아","초식동물","뿔","두꺼운피부","큰동물","육상동물","포유류","빠른달리기","멸종위기종","초원","숲속","강인한","평화로운"}'),
('sloth','나무늘보','Sloth','Folivora','land',20,30,50,70,3,8,'{"남아메리카 열대우림","중앙아메리카 열대우림"}','herbivore','나무늘보는 남아메리카와 중앙아메리카의 따뜻한 열대우림에 살아요. 아주 느리게 움직이는 것으로 유명하며, 대부분의 시간을 나무에 거꾸로 매달려 보낸답니다. 개미핥기와 아주 가까운 친척이에요. 숲속에서 거꾸로 매달려 있는 친구를 보면 나무늘보일 수도 있어요!','나무늘보는 너무 느리게 움직여서 몸에 이끼가 자라기도 해요! 또 일주일에 딱 한 번만 땅으로 내려와서 화장실에 간답니다. 정말 신기하죠?','https://images.unsplash.com/photo-1724521154181-93e3207aa22c?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxTbG90aCUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIxMTk0fDA&ixlib=rb-4.1.0&q=80&w=1080','','{"나무늘보","느림보","초식동물","열대우림","남아메리카","중앙아메리카","나무 위","거꾸로 매달리기","잠꾸러기","나뭇잎 먹이","매달리기 전문가","숲속 친구","느린 움직임"}'),
('tiger','호랑이','Tiger','Panthera tigris','land',10,20,90,110,100,310,'{"아시아"}','carnivore','호랑이는 아시아에 사는 아주 크고 멋진 고양이과 동물이에요. 힘센 몸과 커다란 머리, 그리고 긴 꼬리를 가지고 있어요. 주황색 털에 검은색 줄무늬가 세로로 나 있어서 숲 속에 숨기 정말 좋답니다.','호랑이의 줄무늬는 사람의 지문처럼 모두 달라서, 세상에 똑같은 줄무늬를 가진 호랑이는 단 한 마리도 없어요!','https://images.unsplash.com/photo-1698586582840-a00a2fd7eec4?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxUaWdlciUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIwNzMyfDA&ixlib=rb-4.1.0&q=80&w=1080','','{"아시아","숲","육식동물","줄무늬","고양이과","사냥꾼","힘센동물","단독생활","주황색털","수영선수","멸종위기","커다란발"}'),
('wild-boar','멧돼지','Wild Boar','Sus scrofa','land',4,10,55,110,50,190,'{"숲","초원","관목림","농경지 근처"}','omnivorous','멧돼지는 숲속을 좋아하는 튼튼한 동물 친구예요. 온몸에 억센 털이 나 있고, 뾰족한 이빨을 가지고 있어서 먹이를 찾거나 자신을 지킬 때 사용해요. 아시아, 유럽, 아프리카 등 세상의 아주 많은 곳에서 만날 수 있답니다.','멧돼지는 전 세계에서 가장 넓은 지역에 퍼져 사는 포유류 중 하나래요. 정말 많은 곳에서 멧돼지를 만날 수 있어요!','https://images.unsplash.com/photo-1671374007592-988e8e275469?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxXaWxkJTIwQm9hciUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIxMTUzfDA&ixlib=rb-4.1.0&q=80&w=1080','','{"숲동물","잡식동물","야생동물","큰몸집","억센털","뾰족한이빨","튼튼한코","땅파기","유럽동물","아시아동물","아프리카동물","적응력강함","널리분포하는동물"}'),
('wolf','늑대','Wolf','Canis lupus','land',6,13,60,95,20,80,'{"유라시아","북아메리카"}','carnivore','늑대는 똑똑하고 용감한 동물 친구야! 주로 회색 털을 가졌지만, 어떤 늑대는 하얀색, 갈색, 검은색 털을 가지고 있어. 북아메리카와 유라시아의 넓은 곳에서 살고, 우리 강아지랑도 아주 먼 친척이래!','우리 집에서 키우는 귀여운 강아지가 사실 늑대의 먼 후손이라는 거 알고 있었니? 늑대와 강아지는 아주 오랜 옛날부터 친척 사이였대!','https://images.unsplash.com/photo-1567163056522-a05057f4d719?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxXb2xmJTIwYW5pbWFsfGVufDB8MHx8fDE3Nzc1MjA4ODl8MA&ixlib=rb-4.1.0&q=80&w=1080','','{"포유류","육식동물","야생동물","무리생활","회색늑대","큰개과","유라시아","북아메리카","사냥꾼","울음소리","똑똑한동물","털색깔다양","추운지방"}'),
('zebra','얼룩말','Zebra','Equus','land',0,0,0,0,0,0,'{"사바나","초원","삼림지","관목림","산악 지역"}','omnivore','안녕! 나는 얼룩말이야. 아프리카에 살고, 내 몸에는 멋진 검은색과 흰색 줄무늬가 가득해. 이 줄무늬는 사람의 지문처럼 모두 다 달라서 세상에 똑같은 무늬를 가진 얼룩말은 단 한 마리도 없단다! 말이나 당나귀랑 친척이고, 파리 같은 곤충들이 나를 물지 못하게 막아주는 아주 중요한 역할도 해줘.','놀랍게도 얼룩말의 줄무늬는 사람의 지문처럼 모두 달라서 세상에 똑같은 줄무늬를 가진 얼룩말은 단 한 마리도 없대!','https://images.unsplash.com/photo-1654605889374-d1b2a6af06f0?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5Mzg5MjJ8MHwxfHNlYXJjaHwxfHxaZWJyYSUyMGFuaW1hbHxlbnwwfDB8fHwxNzc3NTIwNzg1fDA&ixlib=rb-4.1.0&q=80&w=1080','','{"아프리카동물","줄무늬동물","흑백무늬","말과친척","당나귀친척","독특한무늬","파리쫓는무늬","사바나동물","초원동물","삼림지동물","관목림동물","산악동물","구별되는무늬"}')
